export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = undefined
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Evaluate thresholds if provided
  if (thresholds) {
    const metricMap = new Map(evaluations.map((m) => [m.id, m]));
    const thresholdResults = [];

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = metricMap.get(metricId);
      if (metric) {
        const score = metric.score;
        const passed = score !== null && score >= min;
        thresholdResults.push({ metric: metricId, min, score, passed });
      }
    }

    report.thresholds = thresholdResults;
    report.passed = thresholdResults.length > 0 ? thresholdResults.every((t) => t.passed) : true;
  } else {
    report.thresholds = [];
    report.passed = true;
  }

  return report;
}

