function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  // Parse thresholds from CLI arguments
  let thresholds: Record<string, number> | undefined;
  if (options.threshold) {
    thresholds = {};
    const thresholdStrings = Array.isArray(options.threshold) ? options.threshold : [options.threshold];

    for (const threshStr of thresholdStrings) {
      const parts = threshStr.split('=');
      if (parts.length !== 2 || !parts[0] || !parts[1]) {
        console.error(`Malformed threshold: '${threshStr}'. Format: --threshold <metric>=<min>`);
        process.exit(2);
      }
      const [metricId, minStr] = parts;
      const min = Number.parseFloat(minStr);
      if (Number.isNaN(min) || min < 0 || min > 1) {
        console.error(`Threshold min must be 0.0–1.0, got '${minStr}' for metric '${metricId}'`);
        process.exit(2);
      }
      thresholds[metricId] = min;
    }
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Validate thresholds against available metric IDs
  if (thresholds) {
    const metricIds = (evaluations as any[]).map((m: any) => m.id);
    const validation = (Eval.validateThresholds as unknown as (config: unknown) => any)(thresholds, metricIds);
    if (!validation.valid) {
      console.error(validation.error);
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on thresholds
  if (!report.passed) {
    process.exit(1);
  }
}

