 * Generate an evaluation report with optional threshold gating.
 * @param {Object} config
 * @param {Array} config.evaluations - Metric evaluation results
 * @param {string} config.outputsPath - Path to outputs file
 * @param {string} config.referencesPath - Path to references file (optional)
 * @param {string} config.generatedAt - Report timestamp (default: now)
 * @param {Object} config.thresholds - Optional thresholds { metric_id: min_score, ... }
 * @returns {Object} Report with passed boolean and thresholds array
 */
export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = undefined
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

